_status": "green", "oa_url": "https://arxiv.org/pdf/2609.39473", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2609.39473", "doi": null, "is_oa": true, "landing_page_url": "https://arxiv.org/abs/2609.39473", "pdf_url": "https://arxiv.org/pdf/2609.39473", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "Autonomous agents increasingly rely on memory to generalize beyond their training environments. However, agents are bounded by what they have seen and believed, and leveraging such memories in unseen environments can introduce biases into their internal beliefs. We formalize this phenomenon as \\textit{false memory}, which can arise from spurious correlations, environment shifts, and knowledge conflicts. Despite its importance, false memory is difficult to evaluate because it stems from agent internal beliefs and is easily confounded with ordinary generalization failures. Therefore, we propose FAME, a training-free framework that evaluates false memory through the evolution of agent beliefs under counterfactual reasoning. Specifically, counterfactual scenarios reveal how beliefs change as the latent concept of memory shifts under hypothetical interventions; thus, measuring the resulting concept drift provides a signal for distinguishing faithful versus false memory. Such concepts can be estimated from agent hidden states before answer generation, avoiding the need for reward design or answer sampling. Empirical experiments reveal that simply monitoring answers often fails to detect false memory, while FAME achieves AUROCs of 76.2% - 96.7% across false-memory settings, and outperforms the best baseline by 3.4% - 23.3% across realistic benchmarks, spanning math reasoning (GSM-Symbolic), code generation (GitChameleon), and complex reasoning (BigBench-Hard). We further release corresponding counterfactual templates and facilitate future research on false memory."}]", "excerpt_truncated": true, "source_sha256": "001cf6954902e0ac946c9e46cc6575b786ca9b5bc0861380de1a5494d3856b70", "verification_required": true, "topic_domain": "memory_formed_preferences", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s11704-024-40231-1", "doi:10.1007/s11704-024-40231-1.pdf", "openalex:W4393065402", "arxiv:2609.39473"], "source_candidates": ["https://doi.org/10.1007/s11704-024-40231-1", "https://link.springer.com/content/pdf/10.1007/s11704-024-40231-1.pdf", "https://arxiv.org/pdf/2609.39473", "https://arxiv.org/abs/2609.39473"], "source_candidate_identities": {}}
